function login() { }

function queryToken() {
  let token = String(source.getVariable())
  if (token.length <= 60) {
    java.toast('请输入有效token')
  } else {
    let res = java.ajax(getApiUrl('/token/test', { token: token }, this))
    let data = JSON.parse(res)
    if (data.code == 0) {
      let info = data.data
      java.longToast(`\n✅查询成功\n用户：${info.id}${info.max ? `\n日下载上限：${info.max}` : ''}\n今日已下载：${info.used}\n日下载剩余：${info.left}\n创建时间：${info.createTime}${info.ddl ? `\n到期时间：${info.ddlTime}` : ''}`)
    } else {
      java.longToast('\n❌查询失败\n' + data.error)
    }
  }
}

function getToken() {
  let pw1 = String(result['源作者'])
  if (pw1 == '') {
    return java.longToast('请输入源作者')
  }
  let pw2 = String(result['官方反馈群'])
  if (pw2 == '') {
    return java.longToast('请输入官方反馈群')
  }
  let pw3 = String(result['临时Token口令'])
  if (pw3 == '') {
    return java.longToast('请输入临时Token口令')
  }
  let res = java.ajax(getApiUrl('/token/temp', { id: java.androidId(), pw1: pw1, pw2: pw2, pw3: pw3 }, this))
  let data = JSON.parse(res)
  if (data.code == 0) {
    let info = data.data
    let token = info.token
    source.setVariable(token)
    java.longToast(`\n✅获取临时token成功\n用户：${info.id}\n日下载剩余：${info.left}\n创建时间：${info.createTime}\n到期时间：${info.ddlTime}`)
    source.putLoginInfo(JSON.stringify(result))
  } else {
    java.longToast('\n❌获取临时token失败\n' + data.error)
  }
}

function settype(type) {
  let pxo = ''
  if (type == '更新') {
    pxo = "update_time"
  } else if (type == '人气') {
    pxo = "hits"
  } else if (type == '数字') {
    pxo = "word"
  }
  source.put('pxo', pxo)
  java.longToast('发现排序已切换为：' + (type || '默认') + '\n长按刷新发现页后生效')
}

function showDb() {
  let res = java.ajax(getApiUrl('/dbinfo', {}, this))
  let data = JSON.parse(res).data
  let tip = `\n【共享数据库信息】\n书籍数：${data.novel_count}\n总章节数：${data.chapter_count}\n总字数：${data.character_count}\n最近更新时间：${data.last_updated}`
  java.longToast(tip)
}

function changeHost(index) {
  if (index < 0 || index >= hosts.length) {
    throw new Error('Invalid host index')
  }
  let host = hosts[index]
  source.put('host', host)
  java.longToast('爱丽丝域名切换为：\n【' + index + '】' + host)
  try {
    let date1 = Date.now()
    let html = java.get(host, { 'user-agent': ua })
    let code = html.statusCode()
    let date2 = Date.now()
    let t = date2 - date1
    let time = t / 1000 + 's'
    let logTime = '【' + host + '】\n┋┋\n' + '解析时间：' + time

    if (code !== 200 || t > 5000) {
      java.longToast('【访问失败提示】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♣️源站已失效(可能被墙)♣️\n┋┋\n请更新网址/切换源站/切换网络环境\n┋┋\n┗┅━┅━┅━┅━┅┅━┅━┅┛')
    } else if (t < 1000) {
      java.longToast('【网络环境优良】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n❤️延迟低，推荐使用此站❤️\n┋┋\n网络环境优良，请继续保持状态\n┋┋\n┗┅━┅━┅━┅━┅┅━┅━┅┛')
    } else if (t >= 1000 && t < 2000) {
      java.longToast('【网络环境一般】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♦️延迟一般，勉强可使用♦️\n┋┋\n请切换其他源站或切换网络环境\n┋┋\n┗┅━┅━┅━┅━┅┅━┅━┅┛')
    } else if (t >= 2000 && t < 5000) {
      java.longToast('【网络环境堪忧】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♠延迟过高，不建议使用♠\n┋┋\n请切换其他源站或切换网络环境\n┋┋\n┗┅━┅━┅━┅━┅┅━┅━┅┛')
    }
  } catch (err) {
    java.toast('\n💔访问出错，请换接口💔')
  }
}

function changeApi(index) {
  if (!index && index !== 0) {
    source.put('hostIndex', '')
    java.longToast('共享api接口已切换为：默认')
  } else {
    source.put('hostIndex', index + '')
    java.longToast('共享api接口已切换为：' + index)
    try {
      let result = java.ajax(getApiUrl('/hostping', { hostIndex: index }, this))
